(()=>{
const core=document.createElement('script');
core.src='https://cdn.jsdelivr.net/gh/Vincentfeliciano11/Cancer-Immunotherapy-Pembrolizumab-@e425b9a0d506eb7d8d3e735f1462bad002f60c9c/effects.js';
core.onload=()=>{
const mobile=matchMedia('(max-width:900px), (hover:none), (pointer:coarse)').matches||navigator.maxTouchPoints>0;if(!mobile)return;
const css=document.createElement('style');css.textContent=`@media(max-width:900px),(hover:none),(pointer:coarse){.comic-panel{color:#fff!important;opacity:1!important;-webkit-text-fill-color:#fff!important;font-weight:1000!important;text-shadow:3px 3px 0 #032048,0 0 2px #032048!important;filter:saturate(1.08) contrast(1.08)!important;-webkit-font-smoothing:antialiased;text-rendering:geometricPrecision}.comic-panel span{color:inherit!important;opacity:1!important;-webkit-text-fill-color:currentColor!important;font-weight:1000!important;text-shadow:inherit!important}.panel-main span{color:#0752ad!important;-webkit-text-fill-color:#0752ad!important;background:#fff!important;opacity:1!important;text-shadow:none!important;border-color:#092e5d!important}.comic-panel:before{opacity:.55!important}.uv-mode .comic-panel{color:#fff!important;opacity:1!important;-webkit-text-fill-color:#fff!important;filter:saturate(1.18) contrast(1.12) brightness(1.08) drop-shadow(0 0 10px #8d2cff) drop-shadow(0 0 18px #13e6ff)!important}.uv-mode .panel-main span{color:#0752ad!important;-webkit-text-fill-color:#0752ad!important;background:#fff!important}}`;document.head.appendChild(css);
let ctx=null;const getCtx=()=>{try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return null;if(!ctx||ctx.state==='closed')ctx=new AC();return ctx}catch(e){return null}};const unlock=()=>{const c=getCtx();if(!c)return;if(c.state==='suspended')c.resume().catch(()=>{});try{const b=c.createBuffer(1,1,22050),s=c.createBufferSource();s.buffer=b;s.connect(c.destination);s.start(0)}catch(e){}};
const comic=()=>{const c=getCtx();if(!c)return;const run=()=>{try{const g=c.createGain(),a=c.createOscillator(),b=c.createOscillator();g.gain.setValueAtTime(.17,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.19);a.type='sawtooth';a.frequency.setValueAtTime(190,c.currentTime);a.frequency.exponentialRampToValueAtTime(520,c.currentTime+.09);b.type='square';b.frequency.setValueAtTime(95,c.currentTime);b.frequency.exponentialRampToValueAtTime(170,c.currentTime+.13);a.connect(g);b.connect(g);g.connect(c.destination);a.start();b.start();a.stop(c.currentTime+.19);b.stop(c.currentTime+.19)}catch(e){}};if(c.state==='suspended')c.resume().then(run).catch(()=>{});else run()};
const click=()=>{const c=getCtx();if(!c)return;const run=()=>{try{const g=c.createGain(),o=c.createOscillator();o.type='square';o.frequency.setValueAtTime(240,c.currentTime);o.frequency.exponentialRampToValueAtTime(115,c.currentTime+.055);g.gain.setValueAtTime(.14,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.075);o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+.08)}catch(e){}};if(c.state==='suspended')c.resume().then(run).catch(()=>{});else run()};
document.addEventListener('touchstart',unlock,{capture:true,passive:true});document.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse')unlock()},{capture:true,passive:true});let lastComic=0,lastUV=0;document.querySelectorAll('.comic-panel').forEach(p=>{p.addEventListener('touchend',()=>{lastComic=performance.now();comic()},{passive:true});p.addEventListener('click',()=>{if(performance.now()-lastComic>500)comic()})});const uv=document.querySelector('.uv-toggle');if(uv){uv.addEventListener('touchend',()=>{lastUV=performance.now();click()},{passive:true});uv.addEventListener('click',()=>{if(performance.now()-lastUV>500)click()})}
};core.onerror=()=>console.error('Unable to load core site effects.');document.head.appendChild(core);
})();